import {mkdir, writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {setTimeout as delay} from 'node:timers/promises';
import type {LanguageModel} from 'ai';
import type {Project} from '../sandbox/project';
import {CHECKER_DIR, CHECKER_SCRIPT} from '../sandbox/runtime-check';
import {PREVIEW_PORT} from '../sandbox/starter';
import {RUNNER_CONFIG} from './config';
import {RATE_LIMITED} from './errors';
import {runAgent} from './run';
import {maskSecrets} from './trace';
import type {ProviderCredential, ProviderId, TurnStatus} from './types';

export type Task = {id: string; prompt: string} & Record<string, unknown>;
export type RunSummary = {taskId: string; run: number; status: TurnStatus; attempts: number; dir: string};

type Deps = {
  model: () => Exclude<LanguageModel, string>;
  project: () => Promise<Project>;
  capture: (project: Project) => Promise<Uint8Array | null>;
  sleep?: (ms: number) => Promise<unknown>;
  log?: (line: string) => void;
};

export function parseTasks(value: unknown): Task[] {
  if (!Array.isArray(value) || value.length === 0) throw new Error('The task file must be a non-empty JSON array.');
  const ids = new Set<string>();
  return value.map((task: Record<string, unknown> | null, i) => {
    const id = task?.id;
    if (typeof id !== 'string' || !/^[\w.-]+$/.test(id)) throw new Error(`Task ${i} needs an id of letters, digits, ".", "-" or "_".`);
    if (typeof task?.prompt !== 'string' || !task.prompt) throw new Error(`Task ${id} needs a prompt.`);
    if (ids.has(id)) throw new Error(`Task id ${id} is used twice.`);
    ids.add(id);
    return task as Task;
  });
}

const EVAL_KEYS: Record<ProviderId, string> = {openai: 'OPENAI_EVAL_API_KEY', anthropic: 'ANTHROPIC_EVAL_API_KEY'};

export function evalCredential(provider: ProviderId, env: Record<string, string | undefined>): ProviderCredential {
  const apiKey = env[EVAL_KEYS[provider]];
  if (!apiKey) throw new Error(`Set ${EVAL_KEYS[provider]} in apps/web/.env. The runner never uses a user key.`);
  return {provider, kind: 'api-key', apiKey};
}

const SHOT = `${CHECKER_DIR}/preview.png`;

export async function previewScreenshot(project: Project, sleep: (ms: number) => Promise<unknown> = delay) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const {exitCode} = await project.run('node', [CHECKER_SCRIPT, `http://localhost:${PREVIEW_PORT}`, SHOT]);
    if (exitCode === 0) return project.readBytes(SHOT);
    await sleep(3_000);
  }
  return null;
}

async function runOnce(task: Task, run: number, outDir: string, deps: Required<Deps>): Promise<RunSummary> {
  for (let attempt = 1; ; attempt++) {
    const project = await deps.project();
    const before = await deps.capture(project);
    const {stream, turn} = runAgent({model: deps.model(), messages: [{role: 'user', content: task.prompt}], project});
    for await (const _ of stream);
    const record = await turn;
    if (record.error === RATE_LIMITED && attempt < RUNNER_CONFIG.maxAttempts) {
      const wait = RUNNER_CONFIG.backoffMs * 2 ** (attempt - 1);
      deps.log(`${task.id} run ${run}: rate limited, retrying in ${wait / 1000}s`);
      await deps.sleep(wait);
      continue;
    }
    const after = await deps.capture(project);
    const dir = join(outDir, task.id, `run-${run}`);
    const json = (value: unknown) => maskSecrets(JSON.stringify(value, null, 2));
    await mkdir(dir, {recursive: true});
    await writeFile(join(dir, 'task.json'), json(task));
    await writeFile(join(dir, 'turn.json'), json(record));
    await writeFile(join(dir, 'diff.patch'), maskSecrets(record.diff));
    await writeFile(join(dir, 'verify.json'), json({verify: record.verify, repairAttempted: record.repairAttempted, repairVerify: record.repairVerify}));
    if (before) await writeFile(join(dir, 'before.png'), before);
    if (after) await writeFile(join(dir, 'after.png'), after);
    deps.log(`${task.id} run ${run}: ${record.status}`);
    return {taskId: task.id, run, status: record.status, attempts: attempt, dir};
  }
}

export async function runTasks({
  tasks,
  runs,
  outDir,
  concurrency = RUNNER_CONFIG.concurrency,
  ...deps
}: {tasks: Task[]; runs: number; outDir: string; concurrency?: number} & Deps): Promise<RunSummary[]> {
  const all: Required<Deps> = {sleep: delay, log: () => {}, ...deps};
  const jobs = tasks.flatMap(task => Array.from({length: runs}, (_, i) => ({task, run: i + 1})));
  const results: RunSummary[] = [];
  let next = 0;
  const worker = async () => {
    while (next < jobs.length) {
      const {task, run} = jobs[next++];
      results.push(await runOnce(task, run, outDir, all));
    }
  };
  await Promise.all(Array.from({length: Math.min(concurrency, jobs.length)}, worker));
  return results;
}
import type {ToolName} from './types';

export const AGENT_CONFIG = {
  maxSteps: 20,
  maxOutputTokens: 8_000,
  tools: ['list_files', 'read_file', 'search', 'edit_file', 'write_file', 'typecheck'] satisfies ToolName[],
  deniedPaths: ['.git', 'node_modules'],
  approvalFiles: ['package.json', 'package-lock.json', '*.lock', 'pnpm-lock.yaml', 'tsconfig*.json', '*.config.*', '.env*'],
  maxToolOutputChars: 20_000,
  promptCachePerProject: true,
} as const;

export const RUNNER_CONFIG = {
  concurrency: 2,
  maxAttempts: 3,
  backoffMs: 5_000,
} as const;
import {APICallError} from 'ai';
import type {ProviderId} from './types';

export const KEY_REJECTED = 'Your API key or sign-in was rejected. Check it and try again.';
export const RATE_LIMITED = 'The model provider is rate limiting requests. Wait a minute and try again.';
export const PROVIDER_FAILED = 'The model provider returned an error. Try again.';
export const VERIFY_FAILED = 'The change still fails its checks after one repair attempt. Restore the previous version or describe what to fix.';
export const STEP_LIMIT = 'The agent hit its step limit before finishing. Send another message to let it continue.';
export const REFUSED = 'The model declined this request. Rephrase it or pick another model.';
export const SANDBOX_FAILED = 'The preview sandbox stopped responding. Reload to try again.';

const PROVIDER_NAMES: Record<ProviderId, string> = {openai: 'OpenAI', anthropic: 'Anthropic'};

export const missingKey = ({provider, label}: {provider: ProviderId; label: string}) =>
  `${provider === 'openai' ? 'Sign in or add' : 'Add'} an ${PROVIDER_NAMES[provider]} API key to use ${label}.`;

// The SDK wraps errors it retried; the provider's status is on the last attempt.
const apiError = (error: unknown) => {
  const last = (error as {lastError?: unknown} | null)?.lastError ?? error;
  return APICallError.isInstance(last) ? last : null;
};

// Never forward provider text: OpenAI's 401 body echoes part of the key. Anthropic 529 overloaded and 5xx fall through to PROVIDER_FAILED.
export function userMessage(error: unknown): string {
  const status = apiError(error)?.statusCode;
  if (status === 401 || status === 403) return KEY_REJECTED;
  if (status === 429) return RATE_LIMITED;
  return PROVIDER_FAILED;
}

export function errorStatus(error: unknown): number | string {
  const api = apiError(error);
  return api ? (api.statusCode ?? 'no-status') : error instanceof Error ? error.name : 'unknown';
}
import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {parseArgs} from 'node:util';
import {RUNNER_CONFIG} from '../src/lib/agent/config';
import {languageModel} from '../src/lib/agent/model';
import {MODELS, providerOf} from '../src/lib/agent/models';
import {evalCredential, parseTasks, previewScreenshot, runTasks} from '../src/lib/agent/runner';
import {flushTraces} from '../src/lib/agent/trace';
import {createSandbox, openProject, sandboxConfigured} from '../src/lib/sandbox/sandbox';

const {values} = parseArgs({
  options: {
    tasks: {type: 'string'},
    runs: {type: 'string', default: '1'},
    concurrency: {type: 'string', default: String(RUNNER_CONFIG.concurrency)},
    model: {type: 'string', default: MODELS[0].id},
    out: {type: 'string', default: `.scratch/agent-runs/${new Date().toISOString().replace(/[:.]/g, '-')}`},
  },
});

const cwd = process.env.INIT_CWD ?? process.cwd();
if (!values.tasks) throw new Error('Usage: bun run agent:run --tasks <file.json> --runs <k> [--concurrency n] [--model id] [--out dir]');
if (!sandboxConfigured()) throw new Error('Set the Vercel sandbox credentials in apps/web/.env.');
const tasks = parseTasks(JSON.parse(readFileSync(resolve(cwd, values.tasks), 'utf8')));
const provider = providerOf(values.model);
if (!provider) throw new Error(`Unknown model ${values.model}. Pick one of: ${MODELS.map(m => m.id).join(', ')}.`);
const credential = evalCredential(provider, process.env);
const outDir = resolve(cwd, values.out);

const results = await runTasks({
  tasks,
  runs: Number(values.runs),
  concurrency: Number(values.concurrency),
  outDir,
  model: () => languageModel(values.model, credential),
  project: async () => openProject((await createSandbox()).sandboxId),
  capture: project => previewScreenshot(project),
  log: line => console.log(line),
});
await flushTraces();
console.log(`${results.length} runs written to ${outDir}`);

