  const {api, calls} = fakeApi();
  expect(await connectSandbox('sbx-test', api)).toEqual({sandboxId: 'sbx-test', previewUrl: `https://sbx-test-${PREVIEW_PORT}.example`});
  expect(calls).toEqual(['get sbx-test resume=true', 'npm run dev &']);
});

